-- SlumsMS 1.6.1 (owner 2026-10-28): Monster Book cards drop from the Arcane River / Grandis mobs. 254 mobs, one card
-- each, 2% (chance 20000, qty 1, not quest-bound), supplied by the owner. The card item ids are Item.wz Consume/0238
-- cards whose info/mob is that mob (checked for all 254).
-- Also adds each card's monstercarddata row (cardid, mobid): ItemInformationProvider.getCardMobId (the book cover
-- packet) unboxes null for a card with no row, and the card-set sizes (MonsterBook.getCardTierSize) count the table.
-- (Its ledger table is still called cards_043_rows: the migration was first applied on TEST as 043.)
-- Only rows this migration really inserts are recorded in cards_043_rows, so the rollback never deletes a pair that
-- was already there. Applying it twice changes nothing (existing pairs are skipped; ledger id '045-newer-area-cards').
-- A running server reads drop_data on boot or on !reloaddrops, and monstercarddata on boot only.
CREATE TABLE IF NOT EXISTS mapleroot_integration_migrations (
  migration_id varchar(100) PRIMARY KEY,
  applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cards_043_rows (
  kind      varchar(16) NOT NULL,
  dropperid int NOT NULL,
  itemid    int NOT NULL,
  PRIMARY KEY (kind, dropperid, itemid)
) ENGINE=InnoDB;

CREATE TEMPORARY TABLE cards_043_pairs (dropperid int NOT NULL, itemid int NOT NULL, PRIMARY KEY (dropperid, itemid));

SELECT 'drop', p.dropperid, p.itemid FROM cards_043_pairs p
 WHERE NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = p.dropperid AND d.itemid = p.itemid);
SELECT r.dropperid, r.itemid, 1, 1, 0, 20000 FROM cards_043_rows r
 WHERE r.kind = 'drop'
   AND NOT EXISTS (SELECT 1 FROM drop_data d WHERE d.dropperid = r.dropperid AND d.itemid = r.itemid);

SELECT 'card', p.dropperid, p.itemid FROM cards_043_pairs p
 WHERE NOT EXISTS (SELECT 1 FROM monstercarddata m WHERE m.cardid = p.itemid);
SELECT r.itemid, r.dropperid FROM cards_043_rows r
 WHERE r.kind = 'card'
   AND NOT EXISTS (SELECT 1 FROM monstercarddata m WHERE m.cardid = r.itemid);

DROP TEMPORARY TABLE cards_043_pairs;
